int rsum(int a[], int lo, int hi) {
    if (lo == hi) {
        return a[lo];
    }
    int mid = lo + (hi - lo) / 2;
    return rsum(a, lo, mid)
         + rsum(a, mid + 1, hi);
}

int rbin(int a[], int lo, int hi,
         int t) {
    if (lo > hi) return -1;
    int mid = lo + (hi - lo) / 2;
    if (a[mid] == t) return mid;
    if (a[mid] < t)
        return rbin(a, mid + 1, hi, t);
    return rbin(a, lo, mid - 1, t);
}
